18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
22	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
23	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
24	    @Mapping(target = "membershipTier", expression = "java(formatMembershipTier(owner))")
25	    OwnerDto toOwnerDto(Owner owner);
26	
27	    /**
28	     * Formats an owner's membership number as {@code "<customerCode>-M<YY>"}, where
29	     * {@code YY} is the last two digits of the registration date's year
30	     * (e.g. {@code "LON-SMI-0007-M26"}). Returns {@code null} until both the customer code
31	     * and registration date have been assigned.
32	     */
33	    default String formatMembershipNumber(Owner owner) {
34	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
35	            return null;
36	        }
37	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
38	    }
39	
40	    /**
41	     * Determines an owner's membership tier: {@code "SILVER"} when the owner has no
42	     * namesakes ({@code namesakeCount} is 0) and an email address on file, otherwise
43	     * {@code "BRONZE"}.
44	     */
45	    default String formatMembershipTier(Owner owner) {
46	        if (owner == null) {
47	            return null;
48	        }
49	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
50	        boolean hasNoNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
51	        return hasNoNamesakes && hasEmail ? "SILVER" : "BRONZE";
52	    }
53	
54	    /**
55	     * Formats an owner's stored names as {@code "LastName, FirstName"} for display.
56	     */
57	    default String formatDisplayName(Owner owner) {
58	        if (owner == null) {
59	            return null;
60	        }
61	        return owner.getLastName() + ", " + owner.getFirstName();
62	    }
63	
64	    /**
65	     * Builds an owner's initials as the upper-cased first letters of the first and last
66	     * name, dot-separated with a trailing dot (e.g. {@code "J.S."}).
67	     */
68	    default String formatInitials(Owner owner) {
69	        if (owner == null) {
70	            return null;
71	        }
72	        return initial(owner.getFirstName()) + initial(owner.getLastName());
73	    }
74	
75	    private String initial(String name) {
76	        return Character.toUpperCase(name.charAt(0)) + ".";
77	    }
78	
79	    Owner toOwner(OwnerDto ownerDto);
80	
81	    @Mapping(target = "id", ignore = true)
